      grassDark: '#245844',
      brick: '#5e4288',
      brickDark: '#2b1c52',
      brickLight: '#b894e8',
      block: '#b8862a',
      blockDark: '#5e3c0a',
      blockLight: '#ffe070',
      stone: '#9c9cc8',
      stoneDark: '#4c4c74',
      stoneLight: '#e4e4ff',
      pipe: '#3a9a6c',
      pipeDark: '#17543c',
      pipeLight: '#9af0b8',
      pole: '#e8f8ff',
      flag: '#ff9ad8',
      castle: '#9c9cc8',
      castleDark: '#4c4c74',
      castleLight: '#e4e4ff',
    },
  };

  // ── Chiptune audio ───────────────────────────────────────────
  const MELODY = [
    'E5','G5','A5','G5','E5','D5','C5','D5',
    'E5','A5','C6','B5','A5','G5','E5','D5',
    'C5','E5','F5','A5','G5','F5','E5','D5',
    'D5','G5','A5','B5','A5','G5','D5','B4',
    'E5','G5','C6','B5','A5','G5','E5','D5',
    'E5','G5','B5','A5','G5','E5','D5','B4',
    'C5','D5','F5','A5','G5','F5','E5','C5',
    'D5','E5','G5','A5','B5','G5','D5','G4',
  ];
  const BASS = ['C3','G2','A2','E2','F2','C3','G2','D3','C3','G2','A2','E2','F2','C3','G2','G2'];
  const NOTE_INDEX = { C: 0, D: 2, E: 4, F: 5, G: 7, A: 9, B: 11 };
  const noteFreq = (name) => {
    if (!name) return 0;
    const letter = name[0];
    const sharp = name[1] === '#';
    const octave = Number(name[sharp ? 2 : 1]);
    const midi = 12 * (octave + 1) + NOTE_INDEX[letter] + (sharp ? 1 : 0);
    return 440 * Math.pow(2, (midi - 69) / 12);
  };

  class Chiptune {
    constructor() {
      this.ctx = null;
      this.master = null;
      this.musicGain = null;
      this.sfxGain = null;
      this.muted = false;
      this.playing = false;
      this.suspended = false;
      this.timer = null;
      this.nextTime = 0;
      this.step = 0;
      this.noiseBuffer = null;
    }

    init() {
      if (this.ctx) {
        if (this.ctx.state === 'suspended') this.ctx.resume().catch(() => {});
        return;
      }
      const AC = window.AudioContext || window.webkitAudioContext;
      if (!AC) return;
      this.ctx = new AC();
      this.master = this.ctx.createGain();
      this.master.gain.value = this.muted ? 0 : 0.72;
      this.master.connect(this.ctx.destination);
      this.musicGain = this.ctx.createGain();
      this.musicGain.gain.value = 0.17;
      this.musicGain.connect(this.master);
      this.sfxGain = this.ctx.createGain();
      this.sfxGain.gain.value = 0.36;
      this.sfxGain.connect(this.master);
      this.makeNoise();
    }

    makeNoise() {
      if (!this.ctx) return;
      const len = Math.floor(this.ctx.sampleRate * 0.25);
      const buf = this.ctx.createBuffer(1, len, this.ctx.sampleRate);
      const data = buf.getChannelData(0);
      let v = 0;
      for (let i = 0; i < len; i++) {
        v = v * 0.55 + (Math.random() * 2 - 1) * 0.45;
        data[i] = v * (1 - i / len);
      }
      this.noiseBuffer = buf;
    }

    setMuted(muted) {
      this.muted = muted;
      if (this.master && this.ctx) {
        this.master.gain.setTargetAtTime(muted ? 0 : 0.72, this.ctx.currentTime, 0.02);
      }
    }

    tone(freq, dur, opts = {}) {
      if (!this.ctx || this.muted) return;
      const {
        type = 'square', vol = 0.16, to = 0, delay = 0, music = false, attack = 0.006
      } = opts;
      const t = this.ctx.currentTime + delay;
      const osc = this.ctx.createOscillator();
      const gain = this.ctx.createGain();
      osc.type = type;
      osc.frequency.setValueAtTime(Math.max(20, freq), t);
      if (to) osc.frequency.exponentialRampToValueAtTime(Math.max(20, to), t + dur);
      gain.gain.setValueAtTime(0.0001, t);
      gain.gain.exponentialRampToValueAtTime(Math.max(0.0002, vol), t + attack);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      osc.connect(gain);
      gain.connect(music ? this.musicGain : this.sfxGain);
      osc.start(t);
      osc.stop(t + dur + 0.02);
    }

    noise(dur = 0.1, vol = 0.12, delay = 0, music = false) {
      if (!this.ctx || this.muted || !this.noiseBuffer) return;
      const t = this.ctx.currentTime + delay;
      const src = this.ctx.createBufferSource();
      src.buffer = this.noiseBuffer;
      const filter = this.ctx.createBiquadFilter();
      filter.type = music ? 'highpass' : 'lowpass';
      filter.frequency.value = music ? 5200 : 1000;
      const gain = this.ctx.createGain();
      gain.gain.setValueAtTime(vol, t);
      gain.gain.exponentialRampToValueAtTime(0.0001, t + dur);
      src.connect(filter);
      filter.connect(gain);
      gain.connect(music ? this.musicGain : this.sfxGain);
      src.start(t);
      src.stop(t + dur + 0.02);
    }

    jump(big) {
      this.tone(big ? 210 : 300, 0.14, { type: 'square', vol: 0.15, to: big ? 560 : 690 });
      this.noise(0.05, 0.025);
    }

    coin() {
      this.tone(988, 0.06, { type: 'square', vol: 0.12 });
      this.tone(1319, 0.16, { type: 'square', vol: 0.12, delay: 0.055 });
    }

    bump() {
      this.tone(140, 0.07, { type: 'square', vol: 0.12, to: 90 });
    }

    brick() {
      this.noise(0.16, 0.16);
      this.tone(160, 0.1, { type: 'square', vol: 0.08, to: 70 });
    }

    stomp() {
      this.tone(240, 0.11, { type: 'square', vol: 0.13, to: 70 });
      this.noise(0.06, 0.06);
    }

    kick() {
      this.tone(280, 0.08, { type: 'square', vol: 0.12, to: 520 });
    }

    fire() {
      this.tone(760, 0.12, { type: 'sawtooth', vol: 0.08, to: 180 });
    }

    power() {
      [523, 659, 784, 1047, 1319].forEach((f, i) =>
        this.tone(f, 0.1, { type: 'square', vol: 0.11, delay: i * 0.065 }));
    }

    oneup() {
      [1047, 1319, 1568, 2093].forEach((f, i) =>
        this.tone(f, 0.11, { type: 'square', vol: 0.1, delay: i * 0.08 }));
    }

    shrink() {
      [420, 330, 240, 180].forEach((f, i) =>
        this.tone(f, 0.09, { type: 'square', vol: 0.1, delay: i * 0.055 }));
    }

    die() {
      [660, 620, 580, 540, 420, 300, 200].forEach((f, i) =>
        this.tone(f, 0.16, { type: 'square', vol: 0.12, delay: i * 0.09, to: f * 0.86 }));
      this.stopMusic();
    }

    clear() {
      this.stopMusic();
      [523, 659, 784, 1047, 1319, 1568].forEach((f, i) =>
        this.tone(f, 0.17, { type: 'square', vol: 0.12, delay: i * 0.11 }));
    }

    gameover() {
      this.stopMusic();
      [392, 330, 262, 196].forEach((f, i) =>
        this.tone(f, 0.28, { type: 'square', vol: 0.12, delay: i * 0.2 }));
    }

    victory() {
      this.stopMusic();
      const notes = [523, 659, 784, 1047, 784, 1047, 1319, 1568];
      notes.forEach((f, i) =>
        this.tone(f, i === notes.length - 1 ? 0.7 : 0.16, {
          type: 'square', vol: 0.13, delay: i * 0.15,
        }));
      [262, 330, 392, 523].forEach((f, i) =>
        this.tone(f, 0.5, { type: 'triangle', vol: 0.1, delay: i * 0.3 }));
    }

    startMusic() {
      if (!this.ctx || this.playing) return;
      this.playing = true;
      this.suspended = false;
      this.step = 0;
      this.nextTime = this.ctx.currentTime + 0.06;
      this.timer = setInterval(() => this.schedule(), 25);
      this.schedule();
    }

    stopMusic() {
      this.playing = false;
      if (this.timer) clearInterval(this.timer);
      this.timer = null;
    }

    pauseMusic() {
      this.suspended = true;
    }

    resumeMusic() {
      if (!this.playing) {
        this.startMusic();
        return;
      }
      this.suspended = false;
      this.nextTime = this.ctx.currentTime + 0.05;
    }

    schedule() {
      if (!this.ctx || !this.playing || this.suspended) return;
      if (this.nextTime < this.ctx.currentTime - 0.25) {
        this.nextTime = this.ctx.currentTime + 0.03;
      }
      const stepDur = 60 / 142 / 2;
      while (this.nextTime < this.ctx.currentTime + 0.14) {
        const i = this.step % MELODY.length;
        if (MELODY[i]) {
          this.tone(noteFreq(MELODY[i]), 0.14, {
            type: 'square', vol: 0.09, music: true,
            delay: Math.max(0, this.nextTime - this.ctx.currentTime),
          });
        }
        if (i % 4 === 0) {
          const b = BASS[Math.floor(i / 4) % BASS.length];
          this.tone(noteFreq(b), stepDur * 3.4, {
            type: 'triangle', vol: 0.13, music: true,
            delay: Math.max(0, this.nextTime - this.ctx.currentTime),
          });
        }
        if (i % 2 === 0) {
          this.noise(0.035, 0.018, Math.max(0, this.nextTime - this.ctx.currentTime), true);
        }
        this.step++;
        this.nextTime += stepDur;
      }
    }
  }

  NES.sound = new Chiptune();
})();

/* levels.js: hand-authored tile maps and spawn tables. */
(() => {
  'use strict';
  const NES = window.NES;

  NES.SOLID = new Set(['#', 'B', '?', 'M', 'S', 'U', '[', ']', '{', '}']);
  NES.isSolidChar = (ch) => NES.SOLID.has(ch);

  function blank(width, theme, name) {
    return {
      width,
      name,
      theme,
      grid: Array.from({ length: NES.ROWS }, () => new Array(width).fill(' ')),
      spawns: [],
      flagTile: width - 14,
      castleTile: width - 9,
      start: { x: 3 * NES.TILE, y: NES.GROUND_Y - 16 },
    };
  }

  const set = (l, x, y, ch) => {
    if (x >= 0 && x < l.width && y >= 0 && y < NES.ROWS) l.grid[y][x] = ch;
  };

  function ground(l, segments) {
    for (const [a, b] of segments) {
      for (let x = a; x <= b; x++) {
        set(l, x, 13, '#');
        set(l, x, 14, '#');
      }
    }
  }

  function pipe(l, x, height) {
    const top = 13 - height;
    set(l, x, top, '[');
    set(l, x + 1, top, ']');
    for (let y = top + 1; y <= 12; y++) {
      set(l, x, y, '{');
      set(l, x + 1, y, '}');
    }
  }

  function row(l, x0, x1, y, ch) {
    for (let x = x0; x <= x1; x++) set(l, x, y, ch);
  }

  function stairUp(l, x, n) {
    for (let i = 0; i < n; i++) {
      for (let y = 12 - i; y <= 12; y++) set(l, x + i, y, 'S');
    }
  }

  function stairDown(l, x, n) {
    for (let i = 0; i < n; i++) {
      for (let y = 12 - (n - 1 - i); y <= 12; y++) set(l, x + i, y, 'S');
    }
  }

  function coins(l, points) {
    for (const [x, y] of points) set(l, x, y, 'o');
  }

  function spawn(l, type, tx, rowY) {
    l.spawns.push({ type, tx, row: rowY == null ? 12 : rowY });
  }

  // ── WORLD 1-1: sunny opening course ─────────────────────────
  function worldOne() {
    const l = blank(212, 'overworld', 'OVERWORLD');
    ground(l, [[0, 68], [71, 85], [88, 152], [155, 183], [186, 211]]);

    set(l, 16, 9, '?');
    set(l, 20, 9, 'B');
    set(l, 21, 9, '?');
    set(l, 22, 9, 'B');
    set(l, 23, 9, 'M');
    set(l, 24, 9, 'B');
    set(l, 22, 5, '?');
    coins(l, [[33, 8], [34, 7], [35, 8], [36, 7]]);

    pipe(l, 28, 2);
    pipe(l, 38, 3);
    pipe(l, 46, 4);
    pipe(l, 57, 4);

    set(l, 64, 9, 'B');
    set(l, 65, 9, '?');
    set(l, 66, 9, 'B');

    set(l, 77, 9, 'B');
    set(l, 78, 9, '?');
    set(l, 79, 9, 'B');
    set(l, 80, 9, 'M');
    set(l, 81, 5, '?');
    coins(l, [[92, 8], [93, 7], [94, 8]]);

    set(l, 96, 9, 'B');
    set(l, 97, 9, '?');
    set(l, 98, 9, 'B');
    set(l, 99, 9, 'B');
    set(l, 100, 9, '?');
    set(l, 101, 9, 'B');
    coins(l, [[104, 7], [105, 6], [106, 7]]);

    pipe(l, 112, 3);
    row(l, 118, 121, 8, 'B');
    set(l, 119, 8, '?');
    coins(l, [[124, 6], [125, 5], [126, 6]]);

    stairUp(l, 134, 4);
    stairDown(l, 140, 4);
    coins(l, [[146, 8], [147, 7], [148, 8]]);

    row(l, 158, 160, 6, 'B');
    set(l, 159, 6, '?');
    coins(l, [[163, 7], [164, 6], [165, 7]]);

    set(l, 168, 9, '?');
    set(l, 169, 9, 'B');
    stairUp(l, 176, 8);

    l.flagTile = 198;
    l.castleTile = 202;
    l.start = { x: 3 * NES.TILE, y: NES.GROUND_Y - 16 };

    const g = [
      ['goomba', 24], ['goomba', 35], ['goomba', 43], ['goomba', 52],
      ['goomba', 62], ['goomba', 74], ['goomba', 82], ['koopa', 90],
      ['goomba', 95], ['goomba', 105], ['goomba', 118], ['goomba', 124],
      ['koopa', 130], ['goomba', 145], ['goomba', 160], ['koopa', 166],
      ['goomba', 169],
    ];
    for (const [type, tx] of g) spawn(l, type, tx);
    return l;
  }

  // ── WORLD 1-2: underground coin cavern ───────────────────────
  function worldTwo() {
