    l.start = { x: 3 * NES.TILE, y: NES.GROUND_Y - 16 };

    const g = [
      ['goomba', 18], ['goomba', 30], ['goomba', 42], ['goomba', 50],
      ['goomba', 62], ['koopa', 66], ['goomba', 70], ['goomba', 88],
