    for (const [type, tx] of g) spawn(l, type, tx);
    return l;
  }

  // ── WORLD 1-3: moonlit gap run ───────────────────────────────
  function worldThree() {
    const l = blank(196, 'night', 'NIGHT RUN');
    ground(l, [[0, 28], [32, 61], [66, 94], [99, 127], [132, 161], [166, 195]]);

    row(l, 10, 13, 9, 'B');
    set(l, 11, 9, '?');
    set(l, 12, 9, 'M');
    set(l, 20, 5, '?');
    coins(l, [[24, 7], [25, 6], [26, 7]]);

