    row(l, 129, 130, 10, 'S');
    coins(l, [[128, 7], [129, 6], [130, 6], [131, 7]]);
    row(l, 136, 139, 6, 'B');
    set(l, 137, 6, '?');
    row(l, 144, 147, 9, 'B');
    set(l, 145, 9, 'M');
    set(l, 152, 5, '?');
    coins(l, [[158, 7], [159, 6], [160, 7]]);

    coins(l, [[162, 7], [163, 6], [164, 7]]);
    stairUp(l, 168, 6);
    stairDown(l, 175, 3);

    l.flagTile = 184;
    l.castleTile = 189;
    l.start = { x: 3 * NES.TILE, y: NES.GROUND_Y - 16 };

    const g = [
      ['goomba', 16], ['goomba', 24], ['goomba', 40], ['koopa', 46],
