  NES.drawFireball = (c, x, y, time) => {
    const f = Math.floor(time * 30) % 2;
    px(c, x, y, 6, 6, '#a51f1b');
    px(c, x + 1, y + 1, 4, 4, f ? '#ff9a3c' : '#ffd24a');
