import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.evaluate(() => window.__MARIO.startRun());
await page.waitForTimeout(1700);

const results = {};
const place = async (x, y, extra = '') => {
  await page.evaluate(({ x, y, extra }) => {
    const m = window.__MARIO;
    m.game.state = 'playing';
    m.game.stateTimer = 0;
    m.game.paused = false;
    m.player.dead = false;
    m.player.invuln = 0;
    m.player.vx = 0;
    m.player.vy = 0;
    m.player.x = x;
    m.player.y = y;
    m.game.camera = Math.max(0, Math.min(m.level.width * 16 - 256, x - 96));
    if (extra === 'clear-enemies') for (const e of m.entities) e.alive = false;
  }, { x, y, extra });
  await page.waitForTimeout(80);
};

// 1. Question block hit
await place(21 * 16 + 2, 192, 'clear-enemies');
await page.keyboard.down('ArrowUp');
await page.waitForTimeout(90);
await page.keyboard.up('ArrowUp');
await page.waitForTimeout(600);
results.block = await page.evaluate(() => ({
  char: __MARIO.level.grid[9][21],
  coins: __MARIO.game.coins,
  score: __MARIO.game.score,
  state: __MARIO.game.state,
  y: Math.round(__MARIO.player.y),
}));

// 2. Mushroom block
await place(23 * 16 + 2, 192, 'clear-enemies');
await page.keyboard.down('ArrowUp');
await page.waitForTimeout(120);
await page.keyboard.up('ArrowUp');
await page.waitForTimeout(500);
results.powerSpawn = await page.evaluate(() => ({
  char: __MARIO.level.grid[9][23],
  powers: __MARIO.powers.map((p) => ({ type: p.type, y: Math.round(p.y), active: p.active })),
}));
await page.waitForTimeout(900);
results.powerWalk = await page.evaluate(() => ({
  powers: __MARIO.powers.map((p) => ({ type: p.type, x: Math.round(p.x), y: Math.round(p.y), active: p.active })),
  power: __MARIO.player.power,
}));

// 3. Stomp a goomba: drop onto one.
await page.evaluate(() => {
  const m = window.__MARIO;
  m.game.state = 'playing';
  m.loadLevel(0, false);
});
await page.waitForTimeout(1600);
results.stomp = await page.evaluate(() => {
  const m = window.__MARIO;
  const e = m.entities.find((en) => en.type === 'goomba');
  m.player.x = e.x;
  m.player.y = e.y - 44;
  m.player.vy = 220;
  m.game.camera = Math.max(0, e.x - 96);
  return { enemyX: e.x, enemyY: e.y };
});
await page.waitForTimeout(500);
results.stompAfter = await page.evaluate(() => {
  const m = window.__MARIO;
  return {
    score: m.game.score,
    playerY: Math.round(m.player.y),
    playerVy: Math.round(m.player.vy),
    enemies: m.entities.filter((e) => e.alive).length,
    state: m.game.state,
  };
});

// 4. Flag and level transition
await page.evaluate(() => {
  const m = window.__MARIO;
  m.game.state = 'playing';
  m.player.power = 0;
  m.player.h = 16;
  m.player.x = m.level.flagTile * 16 - 12;
  m.player.y = 192;
  m.game.camera = m.level.width * 16 - 256;
});
await page.waitForTimeout(400);
results.flag = await page.evaluate(() => ({
  state: __MARIO.game.state,
  timer: +__MARIO.game.stateTimer.toFixed(2),
  score: __MARIO.game.score,
}));
await page.waitForTimeout(3000);
results.nextLevel = await page.evaluate(() => ({
  state: __MARIO.game.state,
  levelIndex: __MARIO.game.levelIndex,
  world: __MARIO.level.name,
}));

// 5. Level 2 and 3 screenshots
await page.evaluate(() => __MARIO.loadLevel(1, false));
await page.waitForTimeout(1600);
await page.evaluate(() => {
  __MARIO.player.x = 20 * 16;
  __MARIO.player.y = 192;
  __MARIO.game.camera = 16 * 16;
});
await page.waitForTimeout(150);
await page.screenshot({ path: 'screenshots/level2b.png' });

await page.evaluate(() => __MARIO.loadLevel(2, false));
await page.waitForTimeout(1600);
await page.evaluate(() => {
  __MARIO.player.x = 12 * 16;
  __MARIO.player.y = 192;
  __MARIO.game.camera = 8 * 16;
});
await page.waitForTimeout(150);
await page.screenshot({ path: 'screenshots/level3b.png' });

console.log(JSON.stringify({ errors, results }, null, 2));
await browser.close();

