import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');

const browser = await chromium.launch({
  executablePath: '/usr/bin/chromium',
  headless: true,
  args: ['--no-sandbox', '--disable-gpu'],
});
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.message));
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.evaluate(() => window.__MARIO.startRun());
await page.waitForTimeout(1700);
const results = {};

const reset = async () => {
  await page.evaluate(() => {
    const m = window.__MARIO;
    m.loadLevel(0, false);
    m.game.state = 'playing';
    m.game.stateTimer = 0;
    for (const e of m.entities) e.alive = false;
  });
  await page.waitForTimeout(120);
};

// Brick break as big Mario
await reset();
await page.evaluate(() => {
  const m = window.__MARIO;
  m.player.power = 1; m.game.power = 1; m.player.h = 28;
  m.player.x = 20 * 16 + 2; m.player.y = 208 - 28;
  m.game.camera = 16 * 16;
});
await page.keyboard.down('ArrowUp');
await page.waitForTimeout(150);
await page.keyboard.up('ArrowUp');
await page.waitForTimeout(500);
results.brick = await page.evaluate(() => ({
  char: __MARIO.level.grid[9][20],
  score: __MARIO.game.score,
  power: __MARIO.player.power,
  h: __MARIO.player.h,
  state: __MARIO.game.state,
}));

// Big Mario hits an M block -> fire flower
await reset();
await page.evaluate(() => {
  const m = window.__MARIO;
  m.player.power = 1; m.game.power = 1; m.player.h = 28;
  m.player.x = 23 * 16 + 2; m.player.y = 208 - 28;
  m.game.camera = 16 * 16;
});
await page.keyboard.down('ArrowUp');
await page.waitForTimeout(150);
await page.keyboard.up('ArrowUp');
await page.waitForTimeout(500);
results.flower = await page.evaluate(() => ({
  char: __MARIO.level.grid[9][23],
  types: NES.powers.map((p) => p.type),
  playerPower: __MARIO.player.power,
}));
// collect it
await page.evaluate(() => {
  const p = NES.powers[0];
  if (p) { __MARIO.player.x = p.x; __MARIO.player.y = p.y; }
});
await page.waitForTimeout(300);
results.flowerCollect = await page.evaluate(() => ({
  playerPower: __MARIO.player.power,
  h: __MARIO.player.h,
  score: __MARIO.game.score,
}));

// Fireball
await page.keyboard.down('KeyX');
await page.waitForTimeout(80);
await page.keyboard.up('KeyX');
await page.waitForTimeout(120);
results.fireball = await page.evaluate(() => ({
  count: NES.fireballs.length,
  vx: NES.fireballs[0] ? Math.round(NES.fireballs[0].vx) : null,
}));

// Flag clear and next level
await page.evaluate(() => {
  const m = window.__MARIO;
  m.game.state = 'playing';
  m.player.x = m.level.flagTile * 16 - 6;
  m.player.y = 192;
  m.player.vx = 0;
  m.game.camera = m.level.width * 16 - 256;
});
await page.waitForTimeout(250);
results.flag = await page.evaluate(() => ({
  state: __MARIO.game.state,
  timer: +__MARIO.game.stateTimer.toFixed(2),
  score: __MARIO.game.score,
}));
await page.waitForTimeout(3100);
results.afterClear = await page.evaluate(() => ({
  state: __MARIO.game.state,
  levelIndex: __MARIO.game.levelIndex,
  lives: __MARIO.game.lives,
  power: __MARIO.player.power,
  world: NES.level.name,
}));

// Death in a pit with one life -> game over
await page.evaluate(() => {
  const m = window.__MARIO;
  m.game.lives = 1;
  m.game.state = 'playing';
  m.player.x = 69 * 16 + 4;
  m.player.y = 192;
  m.player.h = 16;
  m.player.power = 0;
  m.game.camera = 64 * 16;
});
await page.waitForTimeout(1200);
results.fall = await page.evaluate(() => ({ state: __MARIO.game.state, y: Math.round(__MARIO.player.y) }));
await page.waitForTimeout(2200);
results.gameover = await page.evaluate(() => ({
  state: __MARIO.game.state,
  lives: __MARIO.game.lives,
}));
await page.screenshot({ path: 'screenshots/gameover.png' });

// Mobile layout + touch
const mobile = await browser.newContext({
  viewport: { width: 390, height: 844 },
  hasTouch: true,
  isMobile: true,
  deviceScaleFactor: 2,
});
const mp = await mobile.newPage();
const mobileErrors = [];
mp.on('pageerror', (e) => mobileErrors.push(e.message));
await mp.goto('http://localhost:3002', { waitUntil: 'load' });
await mp.waitForTimeout(500);
await mp.screenshot({ path: 'screenshots/mobile-title.png' });
await mp.evaluate(() => window.__MARIO.startRun());
await mp.waitForTimeout(1700);
results.mobile = await mp.evaluate(() => ({
  touchMode: document.body.classList.contains('touch-mode'),
  stage: (() => { const r = document.getElementById('stage').getBoundingClientRect(); return { w: Math.round(r.width), h: Math.round(r.height), x: Math.round(r.x), y: Math.round(r.y) }; })(),
  touchDisplay: getComputedStyle(document.getElementById('touchControls')).display,
  overflow: document.documentElement.scrollWidth <= window.innerWidth,
}));
await mp.screenshot({ path: 'screenshots/mobile-play.png' });
// Tap A to jump
const before = await mp.evaluate(() => __MARIO.player.y);
const a = await mp.locator('.tbtn.a').boundingBox();
await mp.touchscreen.tap(a.x + a.width / 2, a.y + a.height / 2);
await mp.waitForTimeout(180);
const during = await mp.evaluate(() => __MARIO.player.y);
await mp.waitForTimeout(900);
results.mobileJump = { before: Math.round(before), during: Math.round(during), after: Math.round(await mp.evaluate(() => __MARIO.player.y)) };
results.mobileErrors = mobileErrors;
await mobile.close();

console.log(JSON.stringify({ errors, results }, null, 2));
await browser.close();

