227:       const x0 = Math.floor(p.x / TILE);
228:       const x1 = Math.floor((p.x + p.w - 0.01) / TILE);
229:       const hit = [];
230:       let bottom = -Infinity;
231:       for (let tx = x0; tx <= x1; tx++) {
232:         if (solidAt(tx, ty)) {
233:           hit.push([tx, ty]);
234:           bottom = Math.max(bottom, (ty + 1) * TILE);
235:         }
236:       }
237:       if (hit.length) {
238:         p.y = bottom;
239:         p.vy = 0;
240:         for (const [tx, by] of hit) hitBlock(tx, by);
241:       }
242:     }
243:   }
