245:   function updatePlayer(dt) {
246:     const p = player;
247:     p.invuln = Math.max(0, p.invuln - dt);
248:     p.cooldown = Math.max(0, p.cooldown - dt);
249: 
250:     const dir = (held('right') ? 1 : 0) - (held('left') ? 1 : 0);
251:     const running = held('run');
252:     const maxSpeed = running ? NES.RUN_SPEED : NES.WALK_SPEED;
253: 
254:     if (dir !== 0) {
255:       const accel = p.grounded ? NES.ACCEL : NES.AIR_ACCEL;
256:       p.vx += dir * accel * dt;
257:       p.vx = clamp(p.vx, -maxSpeed, maxSpeed);
258:       p.facing = dir;
259:       p.anim += Math.abs(p.vx) * dt * 0.095;
260:     } else {
261:       p.vx = approach(p.vx, 0, NES.FRICTION * dt);
262:       if (Math.abs(p.vx) < 2) p.vx = 0;
263:       if (p.grounded) p.anim += Math.abs(p.vx) * dt * 0.06;
264:     }
265: 
266:     if (p.grounded) p.coyote = NES.COYOTE;
267:     else p.coyote -= dt;
268:     if (jumpBuffer > 0) jumpBuffer -= dt;
269: 
270:     if (jumpBuffer > 0 && p.coyote > 0) {
271:       p.vy = -(NES.JUMP_V + (Math.abs(p.vx) > NES.WALK_SPEED + 4 ? 20 : 0));
272:       p.grounded = false;
273:       p.coyote = 0;
274:       p.jumpGrace = 0.15;
275:       jumpBuffer = 0;
276:       sound.jump(p.power > 0);
277:     }
278:     p.jumpGrace = Math.max(0, p.jumpGrace - dt);
279:     if (!held('jump') && p.jumpGrace <= 0 && p.vy < -60) {
280:       p.vy = Math.max(p.vy, -220);
281:     }
282: 
283:     if (runPressed && p.power === 2 && p.cooldown <= 0) {
284:       spawnFireball();
285:       p.cooldown = 0.32;
286:       sound.fire();
287:     }
288:     runPressed = false;
289: 
290:     p.frame = Math.floor(p.anim) % 4;
291:     movePlayer(dt);
292: 
293:     // Land on the castle / level floor cleanly.
294:     if (p.y > H + 48) killPlayer();
295:   }
