297:   // ── Blocks, coins, power-ups ─────────────────────────────────
298:   function bumpKey(tx, ty) { return tx + ',' + ty; }
299: 
300:   function hitBlock(tx, ty) {
301:     const ch = level.grid[ty][tx];
302:     if (!ch || ch === ' ') return;
303:     bumps.set(bumpKey(tx, ty), 0);
304: 
305:     if (ch === '?') {
306:       level.grid[ty][tx] = 'U';
307:       addCoin(200);
308:       spawnCoinPop(tx * TILE + 4, ty * TILE - 12);
309:     } else if (ch === 'M') {
310:       level.grid[ty][tx] = 'U';
311:       spawnPower(tx, ty);
312:     } else if (ch === 'B') {
313:       if (player.power > 0) {
314:         level.grid[ty][tx] = ' ';
315:         addScore(50);
316:         spawnBrickParticles(tx, ty);
317:         game.shake = 3;
318:         sound.brick();
319:       } else {
320:         sound.bump();
321:       }
322:     } else {
323:       sound.bump();
324:     }
325: 
326:     // Bumping a block flips enemies standing on it.
327:     for (const e of entities) {
328:       if (!e.alive || e.squash > 0) continue;
329:       if (e.x + e.w > tx * TILE && e.x < (tx + 1) * TILE &&
330:         Math.abs(e.y + e.h - ty * TILE) < 7) {
331:         e.alive = false;
332:         addScore(100);
333:         addPopup('100', e.x, e.y - 6);
334:         sound.kick();
335:       }
336:     }
337:   }
