413:   // ── Enemies ──────────────────────────────────────────────────
414:   function moveEntity(e, dt) {
415:     e.x += e.vx * dt;
416:     if (e.x < 0) { e.x = 0; e.vx = Math.abs(e.vx); }
417:     if (e.x + e.w > level.width * TILE) {
418:       e.x = level.width * TILE - e.w; e.vx = -Math.abs(e.vx);
419:     }
420: 
421:     if (e.vx !== 0) {
422:       const dir = Math.sign(e.vx);
423:       const tx = Math.floor((dir > 0 ? e.x + e.w - 0.01 : e.x) / TILE);
424:       const y0 = Math.floor(e.y / TILE);
425:       const y1 = Math.floor((e.y + e.h - 0.01) / TILE);
426:       for (let ty = y0; ty <= y1; ty++) {
427:         if (solidAt(tx, ty)) {
428:           if (dir > 0) e.x = tx * TILE - e.w;
429:           else e.x = (tx + 1) * TILE;
430:           e.vx *= -1;
431:           break;
432:         }
433:       }
434:     }
435: 
436:     e.grounded = false;
437:     e.vy = Math.min(e.vy + NES.GRAVITY * dt, NES.MAX_FALL);
438:     e.y += e.vy * dt;
439: 
440:     if (e.vy >= 0) {
441:       const ty = Math.floor((e.y + e.h - 0.01) / TILE);
442:       const x0 = Math.floor(e.x / TILE);
443:       const x1 = Math.floor((e.x + e.w - 0.01) / TILE);
444:       for (let tx = x0; tx <= x1; tx++) {
445:         if (solidAt(tx, ty)) {
446:           e.y = ty * TILE - e.h;
447:           e.vy = 0;
448:           e.grounded = true;
449:           break;
450:         }
451:       }
452:     } else {
453:       const ty = Math.floor(e.y / TILE);
454:       const x0 = Math.floor(e.x / TILE);
455:       const x1 = Math.floor((e.x + e.w - 0.01) / TILE);
456:       for (let tx = x0; tx <= x1; tx++) {
457:         if (solidAt(tx, ty)) { e.y = (ty + 1) * TILE; e.vy = 0; break; }
458:       }
459:     }
460:   }
