462:   function collideEnemy(e) {
463:     if (!overlap(player, e) || player.sliding) return;
464:     const stomping = player.vy > 0 && player.y + player.h - player.vy * STEP <= e.y + 9;
465: 
466:     if (stomping) {
467:       player.y = e.y - player.h;
468:       player.vy = -300;
469:       if (e.type === 'goomba') {
470:         e.squash = 0.4;
471:         e.vx = 0;
472:         addScore(100);
473:         addPopup('100', e.x + 2, e.y - 4);
474:         sound.stomp();
475:       } else if (!e.shell) {
476:         e.shell = true;
477:         e.kicked = false;
478:         e.y += e.h - 14;
479:         e.h = 14;
480:         e.w = 14;
481:         e.vx = 0;
482:         e.vy = 0;
483:         addScore(100);
484:         addPopup('100', e.x + 2, e.y - 4);
485:         sound.stomp();
486:       } else if (e.vx === 0) {
487:         e.vx = player.x < e.x ? 158 : -158;
488:         e.kicked = true;
489:         addScore(400);
490:         addPopup('400', e.x + 2, e.y - 4);
491:         sound.kick();
492:       } else {
493:         e.vx = 0;
494:         e.kicked = false;
495:         sound.stomp();
496:       }
497:     } else if (e.shell && e.vx === 0) {
498:       e.vx = player.x < e.x ? 164 : -164;
499:       e.kicked = true;
500:       addScore(400);
501:       addPopup('400', e.x + 2, e.y - 4);
502:       sound.kick();
503:     } else {
504:       damagePlayer();
505:     }
506:   }
