508:   function updateEnemies(dt) {
509:     for (const e of entities) {
510:       if (!e.alive) continue;
511:       if (e.squash > 0) {
512:         e.squash -= dt;
513:         if (e.squash <= 0) e.alive = false;
514:         continue;
515:       }
516:       if (e.x > game.camera + 360 || e.x < game.camera - 140) continue;
517:       moveEntity(e, dt);
518:       if (e.y > H + 48) { e.alive = false; continue; }
519: 
520:       if (e.shell && e.kicked && e.vx !== 0) {
521:         for (const other of entities) {
522:           if (other === e || !other.alive || other.squash > 0) continue;
523:           if (overlap(e, other)) {
524:             other.alive = false;
525:             addScore(200);
526:             addPopup('200', other.x, other.y - 4);
527:             sound.stomp();
528:           }
529:         }
530:       }
531:       if (game.state === 'playing') collideEnemy(e);
532:       if (game.state !== 'playing') break;
533:     }
534:   }
