536:   function updatePowers(dt) {
537:     for (let i = powers.length - 1; i >= 0; i--) {
538:       const p = powers[i];
539:       if (!p.active) {
540:         p.emerge -= dt;
541:         const progress = clamp(1 - p.emerge / 0.55, 0, 1);
542:         p.y = p.baseY - progress * TILE;
543:         if (p.emerge <= 0) {
544:           p.active = true;
545:           p.y = p.baseY - TILE;
546:           if (p.type === 'mushroom') p.vx = 34;
547:         }
548:       } else if (p.type === 'mushroom') {
549:         p.x += p.vx * dt;
550:         if (p.x < 0) { p.x = 0; p.vx = Math.abs(p.vx); }
551:         if (p.x + p.w > level.width * TILE) { p.x = level.width * TILE - p.w; p.vx = -Math.abs(p.vx); }
552:         const dir = Math.sign(p.vx);
553:         const tx = Math.floor((dir > 0 ? p.x + p.w - 0.01 : p.x) / TILE);
554:         const y0 = Math.floor(p.y / TILE);
555:         const y1 = Math.floor((p.y + p.h - 0.01) / TILE);
556:         let hit = false;
557:         for (let ty = y0; ty <= y1; ty++) {
558:           if (solidAt(tx, ty)) {
559:             p.x = dir > 0 ? tx * TILE - p.w : (tx + 1) * TILE;
560:             p.vx *= -1; hit = true; break;
561:           }
562:         }
563:         p.vy = Math.min(p.vy + NES.GRAVITY * dt, NES.MAX_FALL);
564:         p.y += p.vy * dt;
565:         if (p.vy > 0) {
566:           const ty = Math.floor((p.y + p.h - 0.01) / TILE);
567:           const x0 = Math.floor(p.x / TILE);
568:           const x1 = Math.floor((p.x + p.w - 0.01) / TILE);
569:           for (let x = x0; x <= x1; x++) {
570:             if (solidAt(x, ty)) { p.y = ty * TILE - p.h; p.vy = 0; break; }
571:           }
572:         }
573:         if (!hit && p.y > H + 32) { powers.splice(i, 1); continue; }
574:       }
575: 
576:       if (p.active && overlap(player, p)) {
577:         if (p.type === 'mushroom') {
578:           if (player.power === 0) setPower(1);
579:           addScore(1000);
580:           addPopup('1000', p.x, p.y - 6, '#ffd24a');
581:         } else {
582:           setPower(2);
583:           addScore(1000);
584:           addPopup('1000', p.x, p.y - 6, '#ffd24a');
585:         }
586:         sound.power();
587:         powers.splice(i, 1);
588:       }
589:     }
590:   }
