592:   function updateFireballs(dt) {
593:     for (let i = fireballs.length - 1; i >= 0; i--) {
594:       const f = fireballs[i];
595:       f.life -= dt;
596:       f.spin += dt * 20;
597:       if (f.life <= 0) { fireballs.splice(i, 1); continue; }
598: 
599:       f.x += f.vx * dt;
600:       if (solidAtPixel(f.x + (f.vx > 0 ? f.w : 0), f.y + f.h / 2)) {
601:         f.vx *= -1;
602:         f.x += f.vx * dt * 2;
603:       }
604: 
605:       f.vy = Math.min(f.vy + 700 * dt, 420);
606:       f.y += f.vy * dt;
607:       if (f.vy > 0 && solidAtPixel(f.x + f.w / 2, f.y + f.h)) {
608:         f.y = Math.floor((f.y + f.h) / TILE) * TILE - f.h;
609:         f.vy = -215;
610:       } else if (f.vy < 0 && solidAtPixel(f.x + f.w / 2, f.y)) {
611:         f.vy = 40;
612:       }
613: 
614:       let hit = false;
615:       for (const e of entities) {
616:         if (!e.alive || e.squash > 0) continue;
617:         if (overlap(f, e)) {
618:           e.alive = false;
619:           addScore(200);
620:           addPopup('200', e.x + 2, e.y - 4, '#ffb84a');
621:           sound.stomp();
622:           for (let k = 0; k < 6; k++) {
623:             particles.push({
624:               type: 'spark', x: e.x + 8, y: e.y + 8,
625:               vx: (Math.random() - 0.5) * 130, vy: (Math.random() - 0.5) * 130,
626:               life: 0.35, max: 0.35, s: 2, color: '#ff9a3c', gravity: 70,
627:             });
628:           }
629:           hit = true;
630:           break;
631:         }
632:       }
633:       if (hit || f.x < -20 || f.x > level.width * TILE + 20) fireballs.splice(i, 1);
634:     }
