639:       const p = particles[i];
640:       p.life -= dt;
641:       if (p.life <= 0) { particles.splice(i, 1); continue; }
642:       p.vy += (p.gravity || 0) * dt;
643:       p.x += p.vx * dt;
644:       p.y += p.vy * dt;
