655:   function updateCamera(dt) {
656:     const target = clamp(player.x - 96 + clamp(player.vx * 0.2, -18, 18), 0, level.width * TILE - W);
657:     game.camera += (target - game.camera) * Math.min(1, dt * 8);
658:     if (Math.abs(target - game.camera) < 0.05) game.camera = target;
