666:   // ── State updates ────────────────────────────────────────────
667:   function update(dt) {
668:     game.elapsed += dt;
669:     if (game.state !== 'title') game.stateTimer += dt;
670: 
671:     if (game.state === 'title') {
672:       game.titleTime += dt;
673:       return;
674:     }
675: 
676:     if (game.state === 'intro') {
677:       if (game.stateTimer > 1.45) {
678:         game.state = 'playing';
679:         game.stateTimer = 0;
680:         if (!sound.playing) sound.startMusic();
681:       }
682:       return;
683:     }
684: 
685:     if (game.state === 'playing') {
686:       game.time -= dt * 2.45;
687:       if (game.time <= 0) { game.time = 0; killPlayer(); return; }
688:       updatePlayer(dt);
689:       updatePowers(dt);
690:       updateEnemies(dt);
691:       updateFireballs(dt);
692:       collectCoins();
693:       updateParticles(dt);
694:       updateBumps(dt);
695:       updateCamera(dt);
696:       game.shake = Math.max(0, game.shake - 26 * dt);
697:       if (game.state === 'playing') checkFlag();
698:       return;
699:     }
700: 
701:     if (game.state === 'dying') {
702:       player.vy += 900 * dt;
703:       player.y += player.vy * dt;
704:       updateParticles(dt);
705:       updateCamera(dt);
706:       if (game.stateTimer > 2.25) {
707:         game.lives--;
708:         if (game.lives <= 0) {
709:           game.state = 'gameover';
710:           game.stateTimer = 0;
711:           sound.gameover();
712:         } else {
713:           game.power = 0;
714:           loadLevel(game.levelIndex, false);
715:           sound.startMusic();
716:         }
717:       }
718:       return;
719:     }
720: 
721:     if (game.state === 'clear') {
722:       const targetY = GROUND_Y - player.h;
723:       if (game.stateTimer < 0.9) {
724:         player.y = Math.min(targetY, player.y + 125 * dt);
725:         game.flagOffset = Math.min(1, game.stateTimer / 0.9) * (GROUND_Y - 48 - 18);
726:       } else {
727:         player.y = targetY;
728:         if (game.stateTimer < 2.35) {
729:           player.x += 62 * dt;
730:           player.facing = 1;
731:           player.anim += dt * 9;
732:           player.frame = Math.floor(player.anim) % 4;
733:         }
734:       }
735:       updateParticles(dt);
736:       updateBumps(dt);
737:       updateCamera(dt);
738:       if (game.stateTimer > 2.8 && !game.transitioned) {
739:         game.transitioned = true;
740:         if (game.levelIndex < NES.BUILDERS.length - 1) {
741:           game.power = player.power;
742:           loadLevel(game.levelIndex + 1, true);
743:           sound.startMusic();
744:         } else {
745:           game.state = 'victory';
746:           game.stateTimer = 0;
747:           sound.victory();
748:         }
749:       }
750:       return;
751:     }
752: 
753:     if (game.state === 'gameover' || game.state === 'victory') {
754:       updateParticles(dt);
755:     }
756:   }
757: 
758:   // ── Input ────────────────────────────────────────────────────
759:   function isMenuState() {
760:     return game.state === 'title' || game.state === 'gameover' || game.state === 'victory';
761:   }
