781:   function togglePause() {
782:     if (game.state !== 'playing' && game.state !== 'intro') return;
783:     game.paused = !game.paused;
784:     if (game.paused) sound.pauseMusic();
785:     else sound.resumeMusic();
786:   }
787: 
788:   function toggleMute() {
