import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
const errors = [];
page.on('pageerror', (e) => errors.push(e.stack || e.message));
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.evaluate(() => window.__MARIO.startRun());
await page.waitForTimeout(1600);

async function runLevel(index) {
  await page.evaluate((index) => {
    const m = window.__MARIO;
    m.loadLevel(index, false);
    m.game.state = 'playing';
    m.game.stateTimer = 0;
    for (const e of m.entities) e.alive = false;
    const key = (type, code) => window.dispatchEvent(new KeyboardEvent(type, { code }));
    key('keyup', 'ArrowRight');
    key('keyup', 'KeyX');
    key('keydown', 'ArrowRight');
    key('keydown', 'KeyX');
    let cooldown = 0;
    let jumping = false;
    if (window.__botTimer) clearInterval(window.__botTimer);
    window.__botTimer = setInterval(() => {
      const g = m.game;
      const p = m.player;
      if (!p) return;
      if (g.state !== 'playing') {
        if (jumping) { key('keyup', 'KeyZ'); jumping = false; }
        return;
      }
      if (!p.grounded || performance.now() < cooldown) return;
      const solid = (tx, ty) => NES.isSolidChar(m.level.grid[ty] && m.level.grid[ty][tx]);
      const feet = Math.floor((p.y + p.h + 1) / 16);
      const front = Math.floor((p.x + p.w + 14) / 16);
      let blocked = false;
      for (let ty = Math.floor((p.y + 6) / 16); ty <= feet; ty++) {
        if (solid(front, ty) || solid(front + 1, ty)) { blocked = true; break; }
      }
      let gap = false;
      for (let tx = front; tx <= front + 1; tx++) {
        if (!solid(tx, 13) && !solid(tx, 14)) gap = true;
      }
      if (blocked || gap) {
        key('keydown', 'KeyZ');
        jumping = true;
        setTimeout(() => { key('keyup', 'KeyZ'); jumping = false; }, 300);
        cooldown = performance.now() + 430;
      }
    }, 40);
  }, index);

  let out = null;
  const samples = [];
  const start = Date.now();
  while (Date.now() - start < 50000) {
    await page.waitForTimeout(300);
    out = await page.evaluate(() => ({
      state: __MARIO.game.state,
      x: Math.round(__MARIO.player.x),
      y: Math.round(__MARIO.player.y),
      max: __MARIO.level.width * 16,
      levelIndex: __MARIO.game.levelIndex,
      lives: __MARIO.game.lives,
      timer: +__MARIO.game.time.toFixed(1),
    }));
    if (samples.length === 0 || samples[samples.length - 1].x !== out.x) samples.push(out);
    if (out.state === 'clear' || out.state === 'dying' || out.state === 'gameover') break;
  }
  await page.evaluate(() => { if (window.__botTimer) clearInterval(window.__botTimer); window.dispatchEvent(new KeyboardEvent('keyup', { code: 'ArrowRight' })); window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyZ' })); window.dispatchEvent(new KeyboardEvent('keyup', { code: 'KeyX' })); });
  await page.screenshot({ path: `screenshots/bot-level${index + 1}.png` });
  return { out, samples: samples.slice(-16) };
}

const results = [];
for (let i = 0; i < 3; i++) results.push(await runLevel(i));
console.log(JSON.stringify({ errors, results }, null, 2));
await browser.close();

import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 900 } });
await page.goto('http://localhost:3002', { waitUntil: 'load' });
await page.evaluate(() => {
  const m = window.__MARIO;
  m.startRun();
  m.game.state = 'playing';
  m.game.stateTimer = 0;
  for (const e of m.entities) e.alive = false;
  const key = (type, code) => window.dispatchEvent(new KeyboardEvent(type, { code }));
  key('keydown', 'ArrowRight'); key('keydown', 'KeyX');
  window.__jumps = [];
  let cooldown = 0, jumping = false;
  window.__botTimer = setInterval(() => {
    const g = m.game, p = m.player;
    if (!p) return;
    if (g.state !== 'playing') { if (jumping) { key('keyup', 'KeyZ'); jumping = false; } return; }
    if (!p.grounded || performance.now() < cooldown) return;
    const solid = (tx, ty) => NES.isSolidChar(m.level.grid[ty] && m.level.grid[ty][tx]);
    const feet = Math.floor((p.y + p.h + 1) / 16);
    const front = Math.floor((p.x + p.w + 14) / 16);
    let blocked = false;
    for (let ty = Math.floor((p.y + 6) / 16); ty <= feet; ty++) if (solid(front, ty) || solid(front + 1, ty)) { blocked = true; break; }
    let gap = false;
    for (let tx = front; tx <= front + 1; tx++) if (!solid(tx, 13) && !solid(tx, 14)) gap = true;
    if (blocked || gap) {
      window.__jumps.push({ x: +p.x.toFixed(1), tile: +(p.x / 16).toFixed(2), y: +p.y.toFixed(1), blocked, gap, t: +(performance.now() / 1000).toFixed(2) });
      key('keydown', 'KeyZ'); jumping = true;
      setTimeout(() => { key('keyup', 'KeyZ'); jumping = false; }, 300);
      cooldown = performance.now() + 430;
    }
  }, 40);
});
for (let i = 0; i < 20; i++) {
  await page.waitForTimeout(500);
  const s = await page.evaluate(() => ({ state: __MARIO.game.state, x: +__MARIO.player.x.toFixed(1), y: +__MARIO.player.y.toFixed(1) }));
  console.log(i, s);
  if (s.state !== 'playing') break;
}
console.log(await page.evaluate(() => window.__jumps));
await browser.close();

