import { createRequire } from 'node:module';
const require = createRequire('/home/runner/.local/share/omgithub-playwright/package.json');
const { chromium } = require('playwright');
const browser = await chromium.launch({ executablePath: '/usr/bin/chromium', headless: true, args: ['--no-sandbox', '--disable-gpu'] });
const sizes = [[320, 568], [360, 640], [390, 844], [768, 1024], [1024, 768], [844, 390], [932, 430], [1180, 820]];
const out = [];
for (const [width, height] of sizes) {
  const context = await browser.newContext({ viewport: { width, height }, hasTouch: true, isMobile: true, deviceScaleFactor: 2 });
  const page = await context.newPage();
  const errors = [];
  page.on('pageerror', (e) => errors.push(e.message));
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => { window.__MARIO.startRun(); window.__MARIO.game.paused = true; });
  await page.waitForTimeout(100);
  const m = await page.evaluate(() => {
    const rect = (sel) => { const r = document.querySelector(sel).getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height) }; };
    return {
      state: __MARIO.game.state,
      body: { sw: document.documentElement.scrollWidth, sh: document.documentElement.scrollHeight, iw: innerWidth, ih: innerHeight },
      stage: rect('#stage'),
      touch: rect('#touchControls'),
      topbar: rect('.topbar'),
      touchMode: document.body.classList.contains('touch-mode'),
      touchDisplay: getComputedStyle(document.querySelector('#touchControls')).display,
      controls: [...document.querySelectorAll('.tbtn')].map((el) => { const r = el.getBoundingClientRect(); return { x: Math.round(r.x), y: Math.round(r.y), w: Math.round(r.width), h: Math.round(r.height), display: getComputedStyle(el).display }; }),
    };
  });
  const visible = m.touchDisplay !== 'none';
  const safe = visible
    ? m.touch.y + m.touch.h <= height + 1 && m.stage.y >= 0 && m.stage.y + m.stage.h <= height
    : true;
  m.safe = safe;
  m.errors = errors;
  out.push({ size: `${width}x${height}`, ...m });
  if ([[320, 568], [844, 390], [768, 1024]].some(([w, h]) => w === width && h === height)) await page.screenshot({ path: `screenshots/layout-${width}x${height}.png` });
  await context.close();
}
console.log(JSON.stringify(out, null, 2));
await browser.close();

